import { useDashboardStore } from "@/stores/dashboard.stores";
import { pageHead } from "@/utils/page-head";
import { trpc } from "@/utils/trpc";
import { useSuspenseQuery } from "@tanstack/react-query";
import { createFileRoute } from "@tanstack/react-router";
import { PortalSelection } from "./-components/portal-selection";
import { PelatihanDashboard } from "./-components/pelatihan-dashboard";
import { PengujianDashboard } from "./-components/pengujian-dashboard";

export const Route = createFileRoute("/(core)/back-office/")({
  component: RouteComponent,
  head: () => pageHead("Portal Administrasi Back-Office"),
});

/**
 * Komponen utama untuk halaman dasbor back-office admin.
 * Menampilkan PortalSelection jika activeMode null,
 * PelatihanDashboard jika activeMode === "pelatihan",
 * atau PengujianDashboard jika activeMode === "pengujian".
 */
function RouteComponent() {
  const { activeMode, setActiveMode } = useDashboardStore();

  const { data: profile } = useSuspenseQuery(
    trpc.platform.auth.profile.queryOptions(),
  );

  if (activeMode === null) {
    return (
      <PortalSelection
        profileName={profile.name}
        setActiveMode={setActiveMode}
      />
    );
  }

  if (activeMode === "pelatihan") {
    return <PelatihanDashboard profileName={profile.name} />;
  }

  if (activeMode === "pengujian") {
    return <PengujianDashboard profileName={profile.name} />;
  }

  return null;
}

